0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3941,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 14.19\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T678,"])self.__next_f.push([1,"One can transcend all the activities of the modes of material nature simply by understanding them properly by learning from the proper souls. The real spiritual master is Kṛṣṇa, and He is imparting this spiritual knowledge to Arjuna. Similarly, it is from those who are fully in Kṛṣṇa consciousness that one has to learn this science of activities in terms of the modes of nature. Otherwise, one’s life will be misdirected. By the instruction of a bona fide spiritual master, a living entity can know of his spiritual position, his material body, his senses, how he is entrapped, and how he is under the spell of the material modes of nature. He is helpless, being in the grip of these modes, but when he can see his real position, then he can attain to the transcendental platform, having the scope for spiritual life. Actually, the living entity is not the performer of different activities. He is forced to act because he is situated in a particular type of body, conducted by some particular mode of material nature. Unless one has the help of spiritual authority, he cannot understand in what position he is actually situated. With the association of a bona fide spiritual master, he can see his real position, and by such an understanding he can become fixed in full Kṛṣṇa consciousness. A man in Kṛṣṇa consciousness is not controlled by the spell of the material modes of nature. It has already been stated in the Seventh Chapter that one who has surrendered to Kṛṣṇa is relieved from the activities of material nature. For one who is able to see things as they are, the influence of material nature gradually ceases."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3941,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"19\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 19\",\"advanced_view_url_path\":\"/en/library/bg/14/advanced-view/#bb3467\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/14/19/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/14/19/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/14/19/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/14/19/\"},{\"display_name\":\"English\",