hunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3959,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 14.22-25\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T778,"])self.__next_f.push([1,"śrī-bhagavān uvāca – the Supreme Personality of Godhead said; prakāśam – illumination; ca – and; pravṛttim – attachment; ca – and; moham – illusion; eva ca – also; pāṇḍava – O son of Pāṇḍu; na dveṣṭi – does not hate; sampravṛttāni – although developed; na nivṛttāni – nor stopping development; kāṅkṣati – desires; udāsīna-vat – as if neutral; āsīnaḥ – situated; guṇaiḥ – by the qualities; yaḥ – one who; na – never; vicālyate – is agitated; guṇāḥ – the qualities; vartante – are acting; iti evam – knowing thus; yaḥ – one who; avatiṣṭhati – remains; na – never; iṅgate – flickers; sama – equal; duḥkha – in distress; sukhaḥ – and happiness; sva-sthaḥ – being situated in himself; sama – equally; loṣṭa – a lump of earth; aśma – stone; kāñcanaḥ – gold; tulya – equally disposed; priya – to the dear; apriyaḥ – and the undesirable; dhīraḥ – steady; tulya – equal; nindā – in defamation; ātma-saṁstutiḥ – and praise of himself; māna – in honor; apamānayoḥ – and dishonor; tulyaḥ – equal; tulyaḥ – equal; mitra – of friends; ari – and enemies; pakṣayoḥ – to the parties; sarva – of all; ārambha – endeavors; parityāgī – renouncer; guṇa-atītaḥ – transcendental to the material modes of nature; saḥ – he; ucyate – is said to be."])self.__next_f.push([1,"26:T55b,Arjuna submitted three different questions, and the Lord answers them one after another. In these verses, Kṛṣṇa first indicates that a person transcendentally situated has no envy and does not hanker for anything. When a living entity stays in this material world embodied by the material body, it is to be understood that he is under the control of one of the three modes of material nature. When he is actually out of the body, then he is out of the clutches of the material modes of nature. But as long as he is not out of the material body, he should be neutral. He should engage himself in the devotional service of the Lord so that his identity with the material body will automatically be forgotten. When one is conscious of the material body, he acts only for sense gratification, but when one transfers the consciousness to Kṛṣṇa, sense gratification automatically stops. One does not need this material body, and he does not need to accept the dictations of the material body. The qualities of the material modes in the body will act, but as spirit soul the self is aloof from such activities. How does he become aloof? He does not desire to enjoy the body, nor does he desire to get out of it. Thus transcendentally situated, the devotee becomes automatically free. He need not try to become free from the influence of the modes of material nature.27:T474,The next question concerns the dealings of a transcendentally situated person. The materially situated person is affected by so-called honor and dishonor offered to the body, but the transcendentally situated person is not affected by such false honor and dishonor. He performs his duty in Kṛṣṇa consciousness and does not mind whether a man honors or dishonors him. He accepts things that are favorable for his duty in Kṛṣṇa consciousness, otherwise he has no necessity of anything material, either a stone or gold. He takes everyone as his dear friend who helps him in his execution of Kṛṣṇa consciousness, and he does not hate his so-called enemy. He is equally disposed and sees everything on an equal level because he knows perfectly well that he has nothing to do with material existence. Social and political issues do not affect him, because he knows the situation of temporary upheavals and disturbances. He does not attempt anything for his own sake. He can attempt anything for Kṛṣṇa, but for his personal self he does not attempt anything. By such behavior one becomes actually transcendentally situated."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3959,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"22-25\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXTS 22-25\",\"advanced_view_url_path\":\"/en/library/bg/14/advanced-view/#bb3482\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/14/22-25/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/14/22-25/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/14/22-25/\"},{\"display_